#include <cassert>
#include <cmath>
#include <vector>
#include <iostream>

struct Triple { double a, b, c; };

double logistic(double x) {
    if (x > 100.0) return 1.0;
    if (x < -100.0) return 0.0;
    return 1.0 / (1.0 + std::exp(-x));
}

Triple fit_outcome_model(const std::vector<double>& x, const std::vector<int>& t, const std::vector<double>& y) {
    size_t n = x.size();
    double xm = 0.0, tm = 0.0, ym = 0.0;
    for (size_t i = 0; i < n; ++i) { xm += x[i]; tm += t[i]; ym += y[i]; }
    xm /= static_cast<double>(n); tm /= static_cast<double>(n); ym /= static_cast<double>(n);

    double stt = 0.0, sxx = 0.0, stx = 0.0, sty = 0.0, sxy = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double ti = t[i] - tm;
        double xi = x[i] - xm;
        double yi = y[i] - ym;
        stt += ti * ti;
        sxx += xi * xi;
        stx += ti * xi;
        sty += ti * yi;
        sxy += xi * yi;
    }
    double den = stt * sxx - stx * stx;
    if (std::fabs(den) < 1e-12) return {ym, 0.0, 0.0};
    double b = (sxy * stx - sty * sxx) / den;
    double c = (sty * stx - sxy * stt) / den;
    double a = ym - b * tm - c * xm;
    return {a, b, c};
}

std::vector<double> estimate_propensity(const std::vector<double>& x, const std::vector<int>& t) {
    size_t n = x.size();
    double beta = 0.0;
    for (int iter = 0; iter < 200; ++iter) {
        double grad = 0.0;
        for (size_t i = 0; i < n; ++i) grad += (t[i] - logistic(beta * x[i])) * x[i];
        beta += 0.05 * grad / static_cast<double>(n);
    }
    std::vector<double> e;
    e.reserve(n);
    for (double xi : x) e.push_back(logistic(beta * xi));
    return e;
}

double aipw_ate(const std::vector<double>& x, const std::vector<int>& t, const std::vector<double>& y) {
    Triple m = fit_outcome_model(x, t, y);
    auto e = estimate_propensity(x, t);
    size_t n = x.size();
    double eps = 0.01;
    double s = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double mu1 = m.a + m.b + m.c * x[i];
        double mu0 = m.a + m.c * x[i];
        double w1 = 1.0 / std::max(e[i], eps);
        double w0 = 1.0 / std::max(1.0 - e[i], eps);
        s += (mu1 - mu0) + t[i] * (y[i] - mu1) * w1 - (1 - t[i]) * (y[i] - mu0) * w0;
    }
    return s / static_cast<double>(n);
}

int main() {
    double aipw_c1 = aipw_ate(X_C1, T_C1, Y_C1);
    double aipw_c2 = aipw_ate(X_C2, T_C2, Y_C2);

    assert(std::abs(aipw_c1 - 2.0) < 0.4);
    assert(std::abs(aipw_c2 - 2.0) < 0.5);

    std::cout << "PASS\n";
    return 0;
}